using DesktopHub.Core;
using DesktopHub.Windows;
internal static class BoundaryChecks
{
 public static async Task Run(Func<string,Func<Task>,Task> check)
 {
  await check("saved layout normalization refuses more than32 placements",()=>{using var f=new Fixture();while(f.Scene.WindowLayout!.Windows.Count<33)f.Scene.WindowLayout.Windows.Add(f.Scene.WindowLayout.Windows[0] with{});Rejected(()=>SceneValidator.Normalize(f.Scene));return Task.CompletedTask;});
  await check("CancelOwner cancels active waiting and never creates late choice tokens",async()=>{using var f=new Fixture();f.Backend.Windows.Clear();f.Scene.WindowLayout!.WaitTimeoutMs=15000;var pending=f.Service.RestoreAsync("manual",f.Scene,default);f.Service.CancelOwner("manual");var finished=await Task.WhenAny(pending,Task.Delay(500));Assert(ReferenceEquals(finished,pending),"owner cancellation must end native wait promptly");var result=await pending;Assert(result.RestoreToken is null&&result.Entries.All(e=>e.Status=="cancelled"),"cancelled wait yields no interactive permission");});
  await check("five-minute capture expiry is monotonic and cancellation revokes authority",()=>{using var f=new Fixture();var clock=new FastTime();var service=new SceneWindowLayoutService(f.Store,a=>a.Target,f.Backend,clock);var capture=service.Capture("a",f.Scene.Id);clock.Advance(TimeSpan.FromMinutes(5));Rejected(()=>service.Save("a",new(f.Scene.Id,capture.CaptureToken,[],false,15000)));capture=service.Capture("a",f.Scene.Id);service.CancelOwner("a");Rejected(()=>service.Save("a",new(f.Scene.Id,capture.CaptureToken,[],false,15000)));return Task.CompletedTask;});
  await check("ninth capture evicts only oldest of eight bounded sessions",()=>{using var f=new Fixture();var first=f.Service.Capture("a",f.Scene.Id);LayoutCapture latest=first;for(var i=0;i<8;i++)latest=f.Service.Capture("a",f.Scene.Id);Rejected(()=>f.Service.Save("a",new(f.Scene.Id,first.CaptureToken,[],false,15000)));f.Service.Save("a",new(f.Scene.Id,latest.CaptureToken,[],false,15000));return Task.CompletedTask;});
  await check("capture and choice share total-eight session retention",async()=>{using var f=new Fixture();var first=f.Service.Capture("a",f.Scene.Id);for(var i=0;i<7;i++)f.Service.Capture("a",f.Scene.Id);f.Backend.Windows.Add(f.Window(2));await f.Service.RestoreAsync("a",f.Scene,default);Rejected(()=>f.Service.Save("a",new(f.Scene.Id,first.CaptureToken,[],false,15000)));});
  await check("capture caps candidate list at128 and declares truncation",()=>{using var f=new Fixture();f.Backend.Windows.Clear();for(var i=0;i<129;i++)f.Backend.Windows.Add(f.Window(i+1));var capture=f.Service.Capture("a",f.Scene.Id);Assert(capture.Candidates.Count==128&&capture.Truncated,"bounded candidate list");return Task.CompletedTask;});
  await check("missing entries share one15000ms deadline",async()=>{using var f=new Fixture();f.Backend.Windows.Clear();f.Scene.WindowLayout!.WaitTimeoutMs=15000;f.Scene.WindowLayout.Windows.Add(f.Scene.WindowLayout.Windows[0] with{});var clock=new FastTime();var service=new SceneWindowLayoutService(f.Store,a=>a.Target,f.Backend,clock);var result=await service.RestoreAsync("a",f.Scene,default);Assert(clock.Elapsed==TimeSpan.FromSeconds(15),"all entries must share deadline");Assert(result.Entries.Count==2&&result.Entries.All(r=>r.Status=="notFound"),"all missing entries report missing");});
  await check("frozen execution layout survives later live scene edits",async()=>{using var f=new Fixture();f.Store.Update(s=>{s.Scenes[0].WindowLayout!.Windows[0].Bounds.Left=600;s.Scenes[0].Actions.Clear();return s;});var result=await f.Service.RestoreAsync("execution-owner",f.Scene,default);Assert(result.Entries[0].Status=="restored"&&f.Backend.Moves[0].Rect.Left==-1700,"restore must consume supplied frozen scene");});
  await check("choice rejects changed title and process-start identity without native movement",async()=>{using var f=new Fixture();f.Scene.WindowLayout!.Windows[0].TitleContains="Document";f.Backend.Windows.Add(f.Window(2));var result=await f.Service.RestoreAsync("a",f.Scene,default);var entry=result.Entries[0];f.Backend.Windows[0]=f.Window(1) with{Title="different"};Rejected(()=>f.Service.Choose("a",new(result.RestoreToken!,[new(entry.EntryToken,entry.Candidates[0].CandidateToken)])));f.Backend.Windows[0]=f.Window(1) with{Started=101};Rejected(()=>f.Service.Choose("a",new(result.RestoreToken!,[new(entry.EntryToken,entry.Candidates[0].CandidateToken)])));Assert(f.Backend.Moves.Count==0,"changed identity must not move");});
  await check("choice shared-window conflicts reject entire batch before movement",async()=>{using var f=new Fixture();f.Scene.WindowLayout!.Windows.Add(f.Scene.WindowLayout.Windows[0] with{});var result=await f.Service.RestoreAsync("a",f.Scene,default);Rejected(()=>f.Service.Choose("a",new(result.RestoreToken!,result.Entries.Select(e=>new LayoutChoice(e.EntryToken,e.Candidates[0].CandidateToken)).ToArray())));Assert(f.Backend.Moves.Count==0,"reject all before first move");});
  await check("maximized state is restored without classifying as fullscreen",async()=>{using var f=new Fixture();f.Scene.WindowLayout!.Windows[0].State="maximized";var result=await f.Service.RestoreAsync("a",f.Scene,default);Assert(f.Backend.Moves[0].State=="maximized"&&result.Entries[0].Status=="restored","state carried to backend");var screen=new LayoutRect(0,0,1920,1080);Assert(Win32WindowLayoutBackend.IsFullscreen(screen,screen,false,0x80000000),"borderless fullscreen rejected");Assert(!Win32WindowLayoutBackend.IsFullscreen(screen,screen,true,0x80000000),"maximized allowed");Assert(!Win32WindowLayoutBackend.IsFullscreen(screen,screen,false,0x00C00000),"captioned normal window allowed");});
  await check("96 and192DPI top-left taskbar conversions preserve negative origins",()=>{var monitor=new LayoutMonitor("m",new(-1920,-1080,1920,1080),new(-1880,-1040,1880,1040),96);var rect=new LayoutRect(-1800,-900,500,400);var workspace=SceneWindowLayoutService.ScreenToWorkspace(rect,monitor);Assert(workspace==new LayoutRect(-1840,-940,500,400),"top and left workspace offsets");Assert(SceneWindowLayoutService.WorkspaceToScreen(workspace,monitor)==rect,"workspace roundtrip");var dip=SceneWindowLayoutService.ToDip(rect,monitor);Assert(dip.Left==80&&dip.Top==140&&dip.Width==500,"96DPI literal");var changed=monitor with{Dpi=192};Assert(SceneWindowLayoutService.ToPixels(dip,changed)==new LayoutRect(-1720,-800,1000,800),"current monitorDPI replaces saved scale");return Task.CompletedTask;});
  await check("elevated windows do not move or create choice permission",async()=>{using var f=new Fixture();f.Backend.Windows[0]=f.Window(1) with{SkipReason="elevated"};var result=await f.Service.RestoreAsync("a",f.Scene,default);Assert(result.RestoreToken is null&&result.Entries[0].Code=="elevated"&&f.Backend.Moves.Count==0,"no move/elevation/choice");});
 }
 static void Assert(bool value,string text){if(!value)throw new Exception(text);}
 static void Rejected(Action action){try{action();}catch(InvalidOperationException){return;}catch(SettingsValidationException){return;}throw new Exception("expected rejection");}
}
sealed class FastTime:TimeProvider
{
 long ticks;public TimeSpan Elapsed=>TimeSpan.FromTicks(ticks);public override long TimestampFrequency=>TimeSpan.TicksPerSecond;public override long GetTimestamp()=>ticks;public void Advance(TimeSpan span)=>ticks+=span.Ticks;
 public override ITimer CreateTimer(TimerCallback callback,object? state,TimeSpan dueTime,TimeSpan period){var timer=new FastTimer();ThreadPool.QueueUserWorkItem(_=>{Advance(dueTime);callback(state);});return timer;}
 sealed class FastTimer:ITimer{public bool Change(TimeSpan dueTime,TimeSpan period)=>false;public void Dispose(){}public ValueTask DisposeAsync()=>ValueTask.CompletedTask;}
}



